  perform pg_temp.try(mode,'PA select '||a.tag,format('select 1 from public."PlatformAccount" where id=%s',a.id));
  perform pg_temp.try(mode,'AI select '||a.tag,format('select 1 from public."AgentIdentifier" where account_id=%s',a.id));
  perform pg_temp.try(mode,'LA select '||a.tag,format('select 1 from public."LocalAccess" where account_id=%s',a.id));
  perform pg_temp.try(mode,'PA update '||a.tag,format('update public."PlatformAccount" set name=name||''x'' where id=%s',a.id));
  perform pg_temp.try(mode,'PA delete '||a.tag,format('delete from public."PlatformAccount" where id=%s',a.id),format('delete from public."AgentIdentifier" where account_id=%s',a.id));
  perform pg_temp.try(mode,'AI update '||a.tag,format('update public."AgentIdentifier" set trusted=true where account_id=%s',a.id));
  perform pg_temp.try(mode,'AI delete '||a.tag,format('delete from public."AgentIdentifier" where account_id=%s',a.id));
  perform pg_temp.try(mode,'AI insert '||a.tag,format('insert into public."AgentIdentifier"(identifier_type,account_id,value,trusted) values (''email'',%s,''new'',false)',a.id));
  perform pg_temp.try(mode,'LA delete '||a.tag,format('delete from public."LocalAccess" where account_id=%s',a.id));
  perform pg_temp.try(mode,'generic '||a.tag,format('select 1 where public.generic_entity_access(%s,''PlatformAccount'')',a.id));
  for s in select * from sp loop
   perform pg_temp.try(mode,'LA insert '||a.tag||' in '||s.tag,format('insert into public."LocalAccess"(account_id,space_id) values (%s,%s)',a.id,s.id));
   perform pg_temp.try(mode,'LA update space '||a.tag||' to '||s.tag,format('update public."LocalAccess" set space_id=%s where account_id=%s',s.id,a.id));
  end loop;
  for b in select * from ac where tag in ('none_u','deditor_u','dpartial_u','deditor_m','deditor_o','nola_m','mix_u') loop
   perform pg_temp.try(mode,'LA update acct '||a.tag||' to '||b.tag,format('update public."LocalAccess" set account_id=%s where account_id=%s',b.id,a.id));
   perform pg_temp.try(mode,'AI update acct '||a.tag||' to '||b.tag,format('update public."AgentIdentifier" set account_id=%s where account_id=%s',b.id,a.id));
  end loop;
 end loop;
 perform pg_temp.try(mode,'PA full count','select 1 from public."PlatformAccount"');
 perform pg_temp.try(mode,'AI full count','select 1 from public."AgentIdentifier"');
 perform pg_temp.try(mode,'LA full count','select 1 from public."LocalAccess"');
 perform pg_temp.try(mode,'PA insert unowned','insert into public."PlatformAccount"(name,platform,account_local_id) values (''z'',''Roam'',''z'')');
end $f$;
SQL
cat > viewcheck.sql <<'SQL'
\echo === view rows per account as caller, vs LocalAccess visible
select pg_temp.login();
create temp table vc as select a.tag, (select count(*) from public.accounts_in_my_partial_spaces v where v.account_id=a.id) vrows, (select count(*) from public."LocalAccess" l where l.account_id=a.id) la_vis, (select count(*) from public."PlatformAccount" p where p.id=a.id) pa_vis from ac a;
select * from vc where tag in ('pr_o','pe_o','dpartial_o','dreader_o','nola_o','none_o') order by 1;
\echo === view ids the caller cannot see in PlatformAccount (must be empty)
select v.account_id from public.accounts_in_my_partial_spaces v where not exists (select 1 from public."PlatformAccount" p where p.id=v.account_id);
reset role;
SQL
cat > report.sql <<'SQL'
\echo === probe totals
select mode, count(*), count(*) filter (where n like 'ERR%') errs, count(*) filter (where n='0') zero, count(*) filter (where n not like 'ERR%' and n<>'0') nonzero from probe_res group by 1;
\echo === distinct errors per probe kind in new
select split_part(probe,' ',1)||' '||split_part(probe,' ',2) k, n, count(*) from probe_res where mode='new' group by 1,2 order by 1,2;
\echo === differences old vs new
select o.probe, o.n as old, nw.n as new from probe_res o full join probe_res nw on o.probe=nw.probe and nw.mode='new' where o.mode='old' and o.n is distinct from nw.n order by 1 limit 60;
select count(*) as diff_count from probe_res o join probe_res nw on o.probe=nw.probe and nw.mode='new' where o.mode='old' and o.n is distinct from nw.n;
SQL
python3 gen.py && docker exec -i supabase_db_test psql -U postgres -d postgres -q -At -F ' | ' < run.sql 2>&1 | tail -60

